import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { shareReplay } from 'rxjs/operators';
import { IBlogPost } from '../pages/blog/blog-post.interface';

@Injectable({ providedIn: 'root' })
export class BlogService {
  static readonly blogContentUrl: string = 'assets/blog';

  private httpClient = inject(HttpClient);

  // Generated by scripts/build-blog.mjs. Cached so the listing and post
  // pages share one request.
  public readonly posts$: Observable<IBlogPost[]> = this.httpClient
    .get<IBlogPost[]>(`${BlogService.blogContentUrl}/index.json`)
    .pipe(shareReplay(1));

  public loadPostHtml(slug: string): Observable<string> {
    return this.httpClient.get(`${BlogService.blogContentUrl}/${slug}.html`, {
      responseType: 'text',
    });
  }
}
